"""Вписать тексты выводов спринта 1 вместо пометок TODO (тексты: Быкова К. Д.).

    python tools/sprint1_texts.py

Каждая запись: (якорь ячейки, начало TODO-абзаца) -> текст. Повторный запуск ничего не ломает:
если TODO уже заменён, запись пропускается.
"""
import json
import re
from pathlib import Path

NB = Path(__file__).resolve().parent.parent / "lab01.ipynb"

TEXTS = {
    ("rv01-desc", "TODO Антонина: природа события"): r"""**Природа события.** pH вина в реальной жизни зависит от других компонентов вина: кислот и солей, сорта винограда, погоды в год сбора, способа приготовления и другого. Мы не можем узнать pH случайно выбранного вина заранее, так как эта величина зависит от множества факторов и у каждого вина она разная. Угадать её по другим измерениям можно, но неточно: по 10 измерениям датасета прогноз объясняет только половину разброса ($R^2 = 0.50$), а ошибка прогноза (0.107) в 10 раз больше шага прибора 0.01. Дело в том, что в нашем датасете есть только определённые значения состава вина, а не все: например, все кислоты записаны одним числом, а калия, который гасит кислотность, нет совсем. Поэтому расчёт не доказывает, что pH нельзя вычислить в принципе. Он показывает, что по нашим данным его вычислить нельзя, и для нас pH ведёт себя как случайная величина.""",
    ("rv01-math", "TODO Антонина: обоснование выбора распределения"): r"""**Почему проверялось нормальное распределение.** Первым мы проверили именно нормальное распределение, так как по центральной предельной теореме величина, на которую действует много маленьких независимых влияний, распределена примерно нормально, а на pH влияет много компонентов вина: разные кислоты, соли, сорт винограда, погода. Но условия теоремы выполняются не полностью: влияния не равны, не независимы и не просто складываются. Гистограмма и Q-Q показывают, что колокол подходит неидеально: правый хвост немного длиннее (асимметрия +0.46), и концы на обоих графиках отходят от нормальной формы. Нормальность не отвергается только на маленькой выборке из 200 вин, где такой небольшой перекос незаметен, а на всех 4898 винах критерии её отвергают ($p \approx 10^{-42}$). По таблице AIC (информационный критерий Акаике: чем меньше число, тем лучше модель описывает данные) нормальное распределение хуже всех, а лучше подходят модели с хвостом вправо: скошенное нормальное и логнормальное со сдвигом (их AIC равны). Поэтому датчик в спринте 2 построен на логнормальном распределении.""",
    ("rv01-resume", "TODO Антонина: вывод своими словами"): r"""**Вывод по pH.**

1. pH случайно выбранного вина нельзя узнать заранее: по 10 другим измерениям его можно угадать только примерно ($R^2 = 0.50$), потому что в датасете есть не весь состав вина.
2. Распределение pH похоже на колокол, но не совсем нормальное: правый хвост длиннее (асимметрия +0.46). На всех винах нормальность отвергается, а лучше подходят логнормальное со сдвигом и скошенное нормальное. Логнормальное выбрано после просмотра таблицы AIC (информационный критерий Акаике: чем меньше число, тем лучше модель описывает данные), поэтому его проверка ($p = 0.056$) немного в нашу пользу.
3. pH связан с кислотностью: прослеживается зависимость, чем больше в вине кислот, тем ниже pH ($\rho = -0.42$). Со спиртом связь слабая ($\rho = +0.15$).
4. По 300 винам можно судить обо всех винах, так как среднее выборки уже похоже на правду: 3.18–3.19 при 3.188 у всех вин. Чем больше выборка, тем точнее оценки.
5. При сравнении белых и красных вин белые получились кислее красных: pH ниже на 0.12. Это из-за особенностей приготовления: красное вино долго настаивают на кожице винограда, и из неё переходит калий, который гасит кислотность, а ещё в красных чаще проводят яблочно-молочное брожение.""",
    ("rv02-desc", "TODO Антонина: природа события"): r"""**Природа события.** Количество кислот в вине зависит от сорта винограда, его зрелости и погоды: в прохладный год виноград кислее. Кислотность и pH одной природы, обе про кислоты, но это не одно и то же: кислотность показывает количество кислоты в вине, а pH показывает, насколько вино ощущается кислым. Поэтому они связаны ($\rho = -0.42$), но одна не определяет другую полностью. Кислотность случайно выбранного вина нельзя узнать заранее: по 10 другим измерениям её можно угадать только примерно ($R^2 = 0.58$, ошибка 0.54 г/дм³ в 5 раз больше шага прибора 0.1). Самое наглядное доказательство дают «двойники»: нашлось 18 групп вин, у которых все остальные 10 измерений совпадают, а кислотность разная. Если бы кислотность вычислялась как зависимая от других измерений, то у одинаковых вин она тоже была бы одинаковой, хотя это не так.""",
    ("rv02-math", "TODO Антонина: обоснование выбора распределения"): r"""**Почему проверялось логнормальное распределение.** Для кислотности взяли логнормальное распределение, так как нормальный колокол может уходить в минус, а кислотность у нас не бывает отрицательной; у логнормального все значения положительные. Также гистограмма кислотности несимметрична (асимметрия +0.65, длинный хвост вправо до 14.2 г/дм³), а нормальный колокол симметричен. После логарифмирования наш скошенный колокол стал больше похож на обычный: асимметрия упала с 0.65 до 0.08. По таблице AIC логнормальное распределение лучше нормального (12044 против 12240), но точно оно не подходит: проверки отвергают и логнормальное без сдвига ($p \approx 10^{-21}$), и со сдвигом ($p \approx 3\cdot 10^{-6}$). Лучшей по AIC оказалась скошенная нормальная (12040.7), но и она точно не подходит. Реальная форма кислотности сложнее любой из простых формул, а на 4898 винах критерий замечает даже небольшие отличия.""",
    ("rv02-resume", "TODO Антонина: вывод своими словами"): r"""**Вывод по кислотности.**

1. Кислотность случайно выбранного вина нельзя узнать заранее: по другим измерениям её можно угадать только примерно ($R^2 = 0.58$), а 18 групп «двойников» с одинаковыми остальными измерениями имеют разную кислотность.
2. pH и кислотность оказались зависимыми величинами, это показали три способа. Корреляция проверяет общую тенденцию, то есть зависимость одной величины от другой: тут зависимость обратная, чем больше кислот, тем ниже pH ($\rho = -0.42$). Хи-квадрат делит вина на 4 группы по pH и 4 группы по кислотности и смотрит, как часто встречается каждая пара групп: если бы величины были независимы, все сочетания встречались бы поровну, а у нас каких-то групп намного больше. Отличие от корреляции в том, что хи-квадрат замечает любую связь, а не только общую тенденцию. В перестановочном тесте pH перемешали, тем самым разорвав любую связь, и ни разу корреляция не вышла такой сильной, как настоящая.
3. Связь средняя, умеренная: $\rho = -0.42$ и $V$ Крамера 0.23 (сила связи по таблице с группами, от 0, когда связи нет, до 1, когда связь полная). На графике облако наклонено вниз, тёмное и плотное только в одном месте, а дальше рассеивается. Поэтому по кислотности pH угадывается лишь примерно.
4. Распределение кислотности несимметричное, с хвостом вправо. После логарифмирования оно стало почти симметричным (асимметрия 0.08), но логнормальная модель точно не подтвердилась ни без сдвига, ни со сдвигом.
5. Все оценки уточняются с ростом выборки, но дисперсия медленнее среднего и медианы: очень кислых вин мало, и попадут ли они в выборку, решает случай, а дисперсия считается через квадраты отклонений, поэтому один выброс сильно на неё влияет.""",
}


def main():
    nb = json.loads(NB.read_text(encoding="utf-8"))
    done = 0
    cells = nb["cells"]
    for (anchor, start), text in TEXTS.items():
        k0 = next((k for k, c in enumerate(cells) if f'id="{anchor}"' in "".join(c["source"])), None)
        if k0 is None:
            continue
        for c in cells[k0:k0 + 4]:   # TODO лежит в ячейке с якорем или в одной из следующих
            src = "".join(c["source"])
            if c["cell_type"] != "markdown" or start not in src:
                continue
            # TODO-абзац: от «**TODO …» до конца абзаца (пустая строка или конец ячейки)
            pat = re.compile(r"\*\*" + re.escape(start) + r"[\s\S]*?(?=\n\n|\Z)(\n\n_Вопросы:_(\n- _.*_)+)?")
            src2, n = pat.subn(lambda m: text, src, count=1)
            if n:
                c["source"] = src2.splitlines(keepends=True)
                done += 1
                break
    NB.write_text(json.dumps(nb, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
    print(f"вписано текстов: {done}")


if __name__ == "__main__":
    main()
